// ─── File: CqrsTradeoffsDemo.java ───
// Multiple package-private classes for a runnable demo showing BOTH the stale-read
// cost and the suitability decision.
package com.bank.cqrstradeoffs;

import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.*;

public class CqrsTradeoffsDemo {

    private static final Logger log = Logger.getLogger("CqrsTradeoffs");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ---- Part 1: demonstrate eventual-consistency COST ----
        WriteStore write = new WriteStore();
        ReadStore read = new ReadStore();
        write.save(new Account("SAV2001", new BigDecimal("1000000")));
        read.put(new BalanceView("SAV2001", new BigDecimal("1000000")));
        ProjectionUpdater projection = new ProjectionUpdater(read);

        // Write side commits the debit.
        Account rajesh = write.find("SAV2001");
        rajesh.debit(new BigDecimal("50000"));
        write.save(rajesh);
        log.info(() -> "WRITE committed: SAV2001 balance now Rs." + rajesh.getBalance());

        // Immediate read BEFORE projection catches up → STALE (the cost).
        log.warning(() -> "STALE READ: BalanceView still shows Rs."
                + read.get("SAV2001").balance());

        // Projection catches up asynchronously.
        projection.on("SAV2001", rajesh.getBalance());
        log.info(() -> "CONSISTENT READ: BalanceView now shows Rs."
                + read.get("SAV2001").balance());

        // ---- Part 2: demonstrate the suitability DECISION (benefit vs cost) ----
        CqrsSuitabilityScorer scorer = new CqrsSuitabilityScorer();

        Workload refData = new Workload("branch-address", 5, 20, false, true);
        log.info(() -> "DECISION branch-address → " + scorer.recommend(refData));

        Workload statements = new Workload("account-statement", 2_000_000, 40_000, true, false);
        log.info(() -> "DECISION account-statement → " + scorer.recommend(statements));
    }
}

// ─── decision/Workload.java ───
// readsPerMin, writesPerMin: traffic. needsScaling: independent scaling required.
// strongReadAfterWrite: every request must see its own write instantly.
record Workload(String name, long readsPerMin, long writesPerMin,
                boolean needsScaling, boolean strongReadAfterWrite) { }

// ─── decision/CqrsSuitabilityScorer.java ───
class CqrsSuitabilityScorer {
    // Returns a recommendation string with reasoning.
    String recommend(Workload w) {
        if (w.strongReadAfterWrite()) {
            return "PLAIN CRUD — needs strong read-after-write; "
                    + "eventual consistency would be a liability";
        }
        double skew = w.writesPerMin() == 0 ? w.readsPerMin()
                : (double) w.readsPerMin() / w.writesPerMin();
        boolean highTraffic = w.readsPerMin() > 10_000;
        if (w.needsScaling() && highTraffic && skew > 5) {
            return "CQRS — read/write skew " + String.format("%.1f", skew)
                    + ":1, high traffic, independent scaling needed; benefits outweigh costs";
        }
        return "PLAIN CRUD — low traffic / no scaling need; "
                + "CQRS overhead not justified";
    }
}

// ─── domain/Account.java (write model) ───
class Account {
    private final String accountId;
    private BigDecimal balance;
    Account(String id, BigDecimal b) { this.accountId = id; this.balance = b; }
    void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("Insufficient");
        balance = balance.subtract(amt);
    }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
}

// ─── read/BalanceView.java (read model) ───
record BalanceView(String accountId, BigDecimal balance) { }

// ─── projection/ProjectionUpdater.java ───
class ProjectionUpdater {
    private final ReadStore read;
    ProjectionUpdater(ReadStore read) { this.read = read; }
    void on(String accountId, BigDecimal newBalance) {
        read.put(new BalanceView(accountId, newBalance));
    }
}

class WriteStore {
    private final Map<String, Account> db = new ConcurrentHashMap<>();
    void save(Account a) { db.put(a.getAccountId(), a); }
    Account find(String id) { return db.get(id); }
}
class ReadStore {
    private final Map<String, BalanceView> db = new ConcurrentHashMap<>();
    void put(BalanceView v) { db.put(v.accountId(), v); }
    BalanceView get(String id) { return db.get(id); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
